const topics=['有机化学','高分子化学','晶体化学','结构推断','方程式与元素化学','热力学与化学平衡','电化学','动力学','分析化学'];
const slugByTopic={'有机化学':'organic','高分子化学':'polymer','晶体化学':'crystal','结构推断':'inference','方程式与元素化学':'elements','热力学与化学平衡':'equilibrium','电化学':'electrochemistry','动力学':'kinetics','分析化学':'analysis'};
const chevron='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>';
const downloadIcon='<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 2v10m-4-4 4 4 4-4M3 13v4h14v-4"/></svg>';
let notes={};let questions=[];let activeTopic='电化学';
function closeMenu(){document.getElementById('sidebar').classList.remove('open');document.getElementById('overlay').classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');}
function render(topic){activeTopic=topic;const list=questions.filter(q=>q.topic===topic);document.title=`${topic} · Chemy 化学竞赛专题题库`;document.getElementById('breadcrumb-topic').textContent=topic;document.getElementById('topic-title').textContent=topic;document.getElementById('topic-summary').textContent=list.length?`${list.length} 道完整大题 · 第 39 届模拟试题 1`:'尚未收录题目';document.getElementById('categories').innerHTML=topics.map(t=>`<button class="category" data-topic="${t}" ${t===topic?'aria-current="page"':''}><span>${t}</span><span class="count">${questions.filter(q=>q.topic===t).length}</span></button>`).join('');document.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>{location.hash=slugByTopic[b.dataset.topic];closeMenu();}));document.getElementById('downloads').innerHTML=list.length&&list.every(q=>q.pdfReady)?`<a class="download" href="downloads/${slugByTopic[topic]}-questions.pdf" download>${downloadIcon}题目 PDF</a><a class="download" href="downloads/${slugByTopic[topic]}-answers.pdf" download>${downloadIcon}答案 PDF</a>`:'';document.getElementById('questions').innerHTML=list.length?`<details class="paper-notes"><summary>本卷提示、常数与评分说明</summary><div class="paper-notes-content"><h3>原卷提示与常用缩写</h3>${notes.instructions||''}<h3>原卷统一评分说明</h3>${notes.scoring||''}</div></details>`+(list.length>1?`<nav class="question-jump" aria-label="本专题题目">${list.map(q=>`<a href="#${slugByTopic[topic]}" data-question="${q.id}">第 ${q.number} 题 · ${q.title}</a>`).join('')}</nav>`:'')+list.map(q=>`<article class="question" id="${q.id}"><div class="q-meta"><span class="topic-badge">${q.topic}</span><span>原卷第 ${q.number} 题</span><span>${q.points} 分</span></div><h2 class="q-title">第 ${q.number} 题　${q.title}（${q.points} 分，占 ${q.percent}%）</h2><div class="q-origin">第 39 届 · 模拟试题 ${q.paper}　题目合集第 ${q.questionPages} 页 · 答案合集第 ${q.answerPages} 页</div><div class="q-body">${q.body}</div><details class="answers"><summary><span>查看参考答案</span>${chevron}</summary><div class="answer-caption">原卷参考答案与评分细则</div><div class="answer-content">${q.answer}</div></details></article>`).join(''):`<section class="empty"><h2>模拟试题 1 暂无该专题题目</h2><p>当前已完整收录模拟试题 1，共 10 道大题。跨专题大题保留完整题干，归入一个主专题。</p><a href="#electrochemistry">阅读电化学题目</a>　<a href="#organic">阅读有机化学题目</a></section>`;document.querySelectorAll('[data-question]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();document.getElementById(a.dataset.question).scrollIntoView({behavior:'smooth',block:'start'});}));document.querySelectorAll('.answers').forEach(d=>d.addEventListener('toggle',()=>{d.querySelector('summary span').textContent=d.open?'收起参考答案':'查看参考答案';}));window.scrollTo({top:0,behavior:'instant'});}
function fromHash(){return topics.find(t=>slugByTopic[t]===location.hash.slice(1))||'有机化学';}
window.addEventListener('hashchange',()=>render(fromHash()));
document.getElementById('menu-toggle').addEventListener('click',()=>{const b=document.getElementById('menu-toggle');const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));document.getElementById('sidebar').classList.toggle('open',open);document.getElementById('overlay').classList.toggle('open',open);});
document.getElementById('overlay').addEventListener('click',closeMenu);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
Promise.all(['questions.json','paper1-notes.json'].map(path=>fetch(path).then(r=>{if(!r.ok)throw new Error('题目加载失败');return r.json();}))).then(([data,common])=>{questions=data;notes=common;document.querySelector('.sidebar-bottom').innerHTML=`<strong>第 39 届 · 模拟题</strong><br>当前收录 ${questions.length} 道完整大题<br>题目与答案保留原卷出处`;render(fromHash());}).catch(()=>{document.getElementById('questions').innerHTML='<section class="empty"><h2>题目暂时无法加载</h2><p>请刷新页面重试。</p></section>';});
